tools.example:
string Dir = dlgDirectory("Select the output folder", cfgget("ULP:myexport.Dir", ""));
if (!Dir) exit(0);                          // cancelled
cfgset("ULP:myexport.Dir", Dir);

board(B) {
  string File = dlgFileSave("Save pick and place file", filesetext(B.name, ".csv"),
                            "CSV files (*.csv);;Text files (*.txt)");
  if (!File) exit(0);
  output(File, "wt") B.elements(E) printf("%s;%.3f;%.3f\n", E.name, u2mm(E.x), u2mm(E.y));
  }
string In = dlgFileOpen("Select order code list", "", "*.txt *.csv");

if (dlgMessageBox("!Delete all <b>unused</b> signals?", "&Yes", "&No") != 0)
   exit(0);
dlgMessageBox(";Done.");
dlgMessageBox(":Could not write <b>parts.csv</b> (file &amp; folder read-only?)");

int Width = 10;
int Result = dlgDialog("Track width") {
  dlgHBoxLayout {
    dlgLabel("&Width (mil):");
    dlgIntEdit(Width, 4, 100);
    }
  dlgHBoxLayout {
    dlgStretch(1);
    dlgPushButton("+OK") dlgAccept();
    dlgPushButton("-Cancel") dlgReject();
    }
  };
if (Result != 1) exit(0);

string Name = "R1", Value = "10k";
dlgGridLayout {
  dlgCell(0, 0) dlgLabel("&Name");
  dlgCell(0, 1) dlgStringEdit(Name);
  dlgCell(1, 0) dlgLabel("&Value");
  dlgCell(1, 1) dlgStringEdit(Value);
  dlgCell(2, 0, 2, 1) dlgLabel("spans two columns");
  }

int Top = 1, Bottom = 0;
dlgGroup("Sides") {
  dlgCheckBox("&Top", Top);
  dlgCheckBox("&Bottom", Bottom) status(Bottom ? "bottom on" : "bottom off");
  }

string Units[] = { "mm", "mil", "inch" };
int Unit = 0;
dlgHBoxLayout {
  dlgLabel("&Unit");
  dlgComboBox(Units, Unit) dlgMessageBox("Selected " + Units[Unit]);
  }

real W = 0.25, C = 0.2;
dlgGridLayout {
  dlgCell(0, 0) dlgLabel("Track &width (mm)");
  dlgCell(0, 1) dlgRealEdit(W, 0.05, 5.0);
  dlgCell(1, 0) dlgLabel("&Clearance (mm)");
  dlgCell(1, 1) dlgRealEdit(C, 0.05, 5.0);
  }

int Side = 0;
dlgGroup("Side") {
  dlgRadioButton("&Top", Side);
  dlgRadioButton("&Bottom", Side);
  dlgRadioButton("B&oth", Side);
  }

dlgHBoxLayout {
  dlgStretch(1);
  dlgPushButton("+OK")    dlgAccept();
  dlgPushButton("Cancel") dlgReject();
  }

int Copies = 1;
dlgHBoxLayout {
  dlgLabel("&Copies (1-10)");
  dlgIntEdit(Copies, 1, 10);
  }

string Info = "Idle";
dlgLabel("<b>Export</b> of the part list");
dlgLabel(Info, 1);                              // updated automatically
dlgPushButton("&Run") { Info = "Running..."; dlgRedisplay(); /* work */ Info = "Finished."; }

string Signals[];
int n = 0, Sel = -1;
board(B) B.signals(S) Signals[n++] = S.name;
dlgDialog("Signals") {
  dlgListBox(Signals, Sel) dlgMessageBox("You picked " + Signals[Sel]);
  dlgPushButton("+OK") dlgAccept();
  };

numeric string Rows[];
int n = 0, Sel = -1, Sort = 1;
board(B) B.elements(E) {
  string r;
  sprintf(r, "%s\t%s\t%s", E.name, E.value, E.footprint.name);
  Rows[n++] = r;
  }
dlgDialog("Parts") {
  dlgListView("Name\tValue\tPackage", Rows, Sel, Sort) dlgMessageBox("Double-clicked " + Rows[Sel]);
  dlgPushButton("+Close") dlgAccept();
  };

int Width = 5, Height = 7;
dlgPushButton("&Reset") { Width = 10; Height = 20; }
dlgPushButton("+&Accept") dlgAccept();
dlgPushButton("-Cancel") { if (dlgMessageBox("Discard changes?", "&Yes", "&No") == 0) dlgReject(); }

int Unit = 0;
dlgGroup("Units") {
  dlgRadioButton("&mm", Unit);
  dlgRadioButton("m&il", Unit);
  dlgRadioButton("&inch", Unit);
  }

real Clearance = 0.2;
dlgHBoxLayout {
  dlgLabel("&Clearance (mm)");
  dlgRealEdit(Clearance, 0.05, 2.0);
  }
// later: int c = mm2u(Clearance);

dlgVBoxLayout {
  dlgLabel("Settings");
  dlgSpacing(10);
  dlgLabel("Output");
  }
dlgHBoxLayout dlgSpacing(350);      // forces a minimum dialog width

int Layers = 2;
dlgHBoxLayout {
  dlgLabel("&Copper layers");
  dlgSpinBox(Layers, 1, 16);
  }

dlgHBoxLayout {
  dlgStretch(1);
  dlgLabel("centered text");
  dlgStretch(1);
  }

string Pattern = "";
string History[];
int n = strsplit(History, cfgget("ULP:find.History"), '\t');
dlgHBoxLayout {
  dlgLabel("&Find");
  dlgStringEdit(Pattern, History, 10);
  }
// after the dialog: cfgset("ULP:find.History", strjoin(History, '\t'));

dlgTabWidget {
  dlgTabPage("&General") { dlgLabel("General options"); }
  dlgTabPage("&Output")  { dlgLabel("Output options"); }
  }

int Page = 0, Opt[];
dlgDialog("Options") {
  dlgTabWidget(Page) {
    for (int i = 0; i < 3; ++i) {
        string s;
        sprintf(s, "Page %d", i + 1);
        dlgTabPage(s) dlgCheckBox("Enable " + s, Opt[i]);
        }
    }
  dlgPushButton("+OK") dlgAccept();
  };

string Notes = "Line 1\nLine 2";
dlgDialog("Assembly notes") {
  dlgLabel("&Notes");
  dlgTextEdit(Notes);
  dlgPushButton("+OK") dlgAccept();
  };
output("notes.txt", "wt") printf("%s\n", Notes);

string Report = "<h3>Check result</h3><ul><li>3 unrouted signals</li>"
                "<li><a href=\"R12\">R12</a> has no value</li></ul>";
string Link;
dlgDialog("Report") {
  dlgTextView(Report, Link) { dlgMessageBox("Clicked " + Link); Link = ""; }
  dlgPushButton("+Close") dlgAccept();
  };

dlgHBoxLayout {
  dlgVBoxLayout {
    dlgLabel("Left column 1");
    dlgLabel("Left column 2");
    }
  dlgVBoxLayout {
    dlgLabel("Right column 1");
    dlgLabel("Right column 2");
    }
  }

tools.usage:
dlgGridLayout { dlgCell(row, col[, row2, col2]) object; ... }
dlgHBoxLayout { object; dlgStretch(1); object; ... }      // left -> right
dlgVBoxLayout { object; dlgSpacing(10); object; ... }     // top -> bottom

tools.example:
dlgDialog("Layout demo") {
  dlgGridLayout {
    dlgCell(0, 0) dlgLabel("Row 0 / Col 0");
    dlgCell(1, 0, 1, 1) dlgGroup("Spanning group") { dlgLabel("..."); }
    }
  dlgHBoxLayout {
    dlgStretch(1);
    dlgPushButton("+OK")    dlgAccept();
    dlgPushButton("Cancel") dlgReject();
    }
  };

int r = dlgDialog("Export") {
  dlgPushButton("+&CSV")  dlgAccept(1);
  dlgPushButton("&Excel") dlgAccept(2);
  dlgPushButton("-Cancel") dlgReject();
  };
if (r == 1) { /* write CSV */ } else if (r == 2) { /* write tab-separated */ }

string Status = "Idle";
dlgDialog("Run") {
  dlgLabel(Status, 1);                        // Update flag set
  dlgPushButton("&Start") {
    Status = "Working...";
    dlgRedisplay();                           // show it now
    board(B) B.signals(S) { /* long task */ }
    Status = "Finished.";
    }
  dlgPushButton("+Close") dlgAccept();
  };

int Number = 1;
dlgDialog("Test") {
  dlgIntEdit(Number, 0, 100);
  dlgPushButton("+OK")    dlgAccept();
  dlgPushButton("&Reset") dlgReset();
  dlgPushButton("Cancel") dlgReject();
  };

int r = dlgDialog("Confirm") {
  dlgLabel("Proceed with the export?");
  dlgPushButton("+OK")     dlgAccept();
  dlgPushButton("-Cancel") dlgReject(-1);
  };
if (r <= 0) exit(0);

string Rows[] = { "R1\t10k", "C1\t100n", "U1\tATmega328" };
int Sel = 0;
string Detail;
dlgDialog("Parts") {
  dlgLabel(Detail, 1);
  dlgListView("Name\tValue", Rows, Sel) {
    if (dlgSelectionChanged()) Detail = Rows[Sel];
    else dlgMessageBox("Opened " + Rows[Sel]);
    }
  dlgPushButton("+OK") dlgAccept();
  };

dlgDialog("About") {
  dlgLabel("Sim \\& Layout Tools");
  dlgPushButton("\\-5 mm") { /* shift by -5 mm */ }
  dlgPushButton("+OK") dlgAccept();
  };

int hor = 1, ver = 1;
string fileName;
int Result = dlgDialog("Enter Parameters") {
  dlgHBoxLayout { dlgStretch(1); dlgLabel("This is a simple dialog"); dlgStretch(1); }
  dlgHBoxLayout {
    dlgGroup("Horizontal") {
      dlgRadioButton("&Top", hor); dlgRadioButton("&Center", hor); dlgRadioButton("&Bottom", hor);
      }
    dlgGroup("Vertical") {
      dlgRadioButton("&Left", ver); dlgRadioButton("C&enter", ver); dlgRadioButton("&Right", ver);
      }
    }
  dlgHBoxLayout {
    dlgLabel("File &name:");
    dlgStringEdit(fileName);
    dlgPushButton("Bro&wse") { fileName = dlgFileOpen("Select a file", fileName); }
    }
  dlgGridLayout {
    dlgCell(0, 0) dlgLabel("Row 0/Col 0");
    dlgCell(0, 1) dlgLabel("Row 0/Col 1");
    }
  dlgSpacing(10);
  dlgHBoxLayout {
    dlgStretch(1);
    dlgPushButton("+OK")    dlgAccept();
    dlgPushButton("Cancel") dlgReject();
    }
  };
if (Result != 1) exit(0);

string Html = "<h2>BOM check</h2>"
              "<table border=1 cellpadding=3>"
              "<tr><th>Part</th><th>Problem</th></tr>"
              "<tr><td>R12</td><td><font color=red>no value</font></td></tr>"
              "</table><p>Tolerance &plusmn;1&nbsp;%</p>";
dlgDialog("Report") { dlgTextView(Html); dlgPushButton("+OK") dlgAccept(); };
